import React, { useState } from "react";
import HoneyComb from "../Assets/honeycomb.png";
import HoneyAmla from "../Assets/honeyamla.png";
import HoneyGarlic from "../Assets/honeygarlic.png";
import OriginalHoney from "../Assets/originalhoney.jpeg";

const products = [
  {
    id: 1,
    name_en: "Pure Forest Honey",
    name_ta: "தூய காட்டு தேன்",
    price: "₹450",
    image: OriginalHoney,
  },
  {
    id: 2,
    name_en: "Wildflower Honey",
    name_ta: "காட்டு மலர் தேன்",
    price: "₹380",
    image: HoneyComb,
  },
  {
    id: 3,
    name_en: "Honey with Amla",
    name_ta: "நெல்லிக்காய் தேன்",
    price: "₹520",
    image: HoneyAmla,
  },
  {
    id: 4,
    name_en: "Honey with Garlic",
    name_ta: "பூண்டு தேன்",
    price: "₹520",
    image: HoneyGarlic,
  },
];

function Home() {
  const [language, setLanguage] = useState("en");

  return (
    <div>
      {/* Navbar */}
      <nav className="navbar navbar-expand-lg navbar-dark bg-warning px-4">
        <a className="navbar-brand fw-bold" href="#">
          O.I.HONEY WORLD
        </a>
        <div className="ms-auto">
          <a className="nav-link d-inline text-dark" href="#products">
            {language === "en" ? "Products" : "பொருட்கள்"}
          </a>
          <a className="nav-link d-inline text-dark" href="#contact">
            {language === "en" ? "Contact" : "தொடர்பு"}
          </a>
        </div>
      </nav>

      {/* Language Toggle */}
      <div className="text-end px-4 py-2 bg-light">
        <button
          className={`btn btn-sm me-2 ${
            language === "en" ? "btn-warning" : "btn-outline-warning"
          }`}
          onClick={() => setLanguage("en")}
        >
          English
        </button>
        <button
          className={`btn btn-sm ${
            language === "ta" ? "btn-warning" : "btn-outline-warning"
          }`}
          onClick={() => setLanguage("ta")}
        >
          தமிழ்
        </button>
      </div>

      {/* Hero Section */}
      <section className="text-center py-5 bg-light">
        <h1 className="fw-bold">
          {language === "en"
            ? "100% Natural & Pure Honey 🍯"
            : "100% இயற்கை மற்றும் தூய தேன் 🍯"}
        </h1>
        <p className="lead">
          {language === "en"
            ? "Fresh from the farm. No additives. No chemicals."
            : "பண்ணையிலிருந்து நேரடியாக. சேர்க்கைகள் இல்லை. ரசாயனங்கள் இல்லை."}
        </p>
        <button className="btn btn-warning btn-lg">
          {language === "en" ? "Shop Now" : "இப்போது வாங்குங்கள்"}
        </button>
      </section>

      {/* Products */}
      <section id="products" className="container py-5">
        <h2 className="text-center mb-4 fw-bold">
          {language === "en" ? "Our Products" : "எங்கள் பொருட்கள்"}
        </h2>

        <div className="row">
          {products.map((product) => (
            <div key={product.id} className="col-md-4 mb-4">
              <div className="card shadow">
                <img
                  src={product.image}
                  className="card-img-top"
                  alt={product.name_en}
                  style={{ height: "250px", objectFit: "cover" }}
                />
                <div className="card-body text-center">
                  <h5 className="card-title">
                    {language === "en"
                      ? product.name_en
                      : product.name_ta}
                  </h5>
                  <p className="text-warning fw-bold">
                    {product.price}
                  </p>
                  <button className="btn btn-warning">
                    {language === "en"
                      ? "Buy Now"
                      : "இப்போது வாங்க"}
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Contact */}
      <section id="contact" className="bg-light text-center py-5">
        <h2 className="fw-bold">
          {language === "en" ? "Contact Us" : "தொடர்பு கொள்ள"}
        </h2>
        <p>📞 +91 9715123277</p>
        <p>📍 1/14, Sivankudiyetru, Padukapathu, Thoothukudi, Tamil Nadu - 628 703</p>
      </section>

      {/* Footer */}
      <footer className="bg-warning text-center py-3">
        <strong>
          © 2026 O.I.HONEY WORLD
        </strong>
      </footer>
    </div>
  );
}

export default Home;
